const input = $input.all();
const data = input[0].json;
const keysToSearch = $('Start').item.json.model_names;
const nodes = data.workflowData?.nodes ?? [];
const totals = {
	completionTokens: 0,
	promptTokens: 0,
	totalTokens: 0,
};
const models = new Set();
const detailedUsages = [];

let aiPolitics = 0;
let aiTech = 0;
let inputRelevance = 0;

function accumulate(usage, model) {
	if (
		typeof usage.completionTokens === 'number' &&
		typeof usage.promptTokens === 'number' &&
		typeof usage.totalTokens === 'number'
	) {
		totals.completionTokens += usage.completionTokens;
		totals.promptTokens += usage.promptTokens;
		totals.totalTokens += usage.totalTokens;
		if (model) models.add(model);
		detailedUsages.push({
			model,
			usage: { ...usage },
		});
	}
}

function findTokenUsageRecursively(obj, model) {
	if (typeof obj !== 'object' || obj === null) return;
	if (
		typeof obj.completionTokens === 'number' &&
		typeof obj.promptTokens === 'number' &&
		typeof obj.totalTokens === 'number'
	) {
		accumulate(obj, model);
		return;
	}
	if (Array.isArray(obj)) {
		obj.forEach((item) => findTokenUsageRecursively(item, model));
	} else {
		const detectedModel = obj.model || model;
		for (const key in obj) {
			if (Object.prototype.hasOwnProperty.call(obj, key)) {
				findTokenUsageRecursively(obj[key], detectedModel);
			}
		}
	}
}

function processExecution(exec, nodeName) {
	const node = nodes.find((n) => n.name === nodeName);
	const model = node?.parameters?.modelName || node?.parameters?.model || node?.parameters?.name;
	findTokenUsageRecursively(exec, model);
}

function extractStatistics() {
	const aggregateStats = data.data?.resultData?.runData?.['Aggregate statistics'];

	if (!aggregateStats || !Array.isArray(aggregateStats)) return;

	aggregateStats.forEach(execution => {
		const mainData = execution?.data?.main?.[0]?.[0]?.json?.data;

		if (!Array.isArray(mainData)) return;

		mainData.forEach(item => {
			if (typeof item.ai_politics === 'number') {
				aiPolitics = item.ai_politics;
			}
			if (typeof item.ai_tech === 'number') {
				aiTech = item.ai_tech;
			}
			if (typeof item.input_relevance === 'number') {
				inputRelevance = item.input_relevance;
			}
		});
	});
}

for (const key of keysToSearch) {
	const executions = data.data?.resultData?.runData?.[key];
	if (!executions) continue;
	if (Array.isArray(executions)) {
		executions.forEach((exec) => processExecution(exec, key));
	} else if (typeof executions === 'object') {
		processExecution(executions, key);
	}
}

extractStatistics();

return [
	{
		json: {
			totals,
			models: Array.from(models),
			detailedUsages,
			statistics: {
				ai_politics: aiPolitics,
				ai_tech: aiTech,
				input_relevance: inputRelevance
			}
		},
		pairedItem: [{ item: 0 }] 
	},
];

const input = $items("map json", 0);;
const data = input[0].json;

function calculateTokensByModel(data) {
  const result = {};

  if (!data.detailedUsages || !Array.isArray(data.detailedUsages)) {
    return result;
  }

  data.detailedUsages.forEach(usage => {
    const model = usage.model;

    if (!model || !usage.usage) {
      return;
    }

    if (!result[model]) {
      result[model] = {
        completionTokens: 0,
        promptTokens: 0,
        totalTokens: 0
      };
    }

    result[model].completionTokens += usage.usage.completionTokens || 0;
    result[model].promptTokens += usage.usage.promptTokens || 0;
    result[model].totalTokens += usage.usage.totalTokens || 0;
  });

  return result;
}

const tokensByModel = calculateTokensByModel(data);

return [
  {
    json: {
      tokensByModel,
      summary: {
        totalModels: Object.keys(tokensByModel).length,
        models: Object.keys(tokensByModel)
      }
    },
    pairedItem: [{ item: 0 }]
  }
];

const input = $input.all();
const data = input[0].json.tokensByModel;

const PRICING = {
  'models/gemini-2.5-flash-lite': {
    input: 0.10,
    output: 0.40
  },
  'models/gemini-3-flash-preview': {
    input: 0.5,
    output: 3.00
  },
  'models/gemini-3-pro-preview': {
    input: 2.00,
    output: 12.00
  }
};

function calculateCosts(tokensByModel) {
  const results = [];
  let totalCost = 0;

  for (const model in tokensByModel) {
    const tokens = tokensByModel[model];
    const pricing = PRICING[model];

    const inputCost = (tokens.promptTokens / 1000000) * pricing.input;
    const outputCost = (tokens.completionTokens / 1000000) * pricing.output;
    const modelTotalCost = inputCost + outputCost;

    totalCost += modelTotalCost;

    results.push({
      model,
      tokens: {
        promptTokens: tokens.promptTokens,
        completionTokens: tokens.completionTokens,
        totalTokens: tokens.totalTokens
      },
      costs: {
        inputCost: Number(inputCost.toFixed(6)),
        outputCost: Number(outputCost.toFixed(6)),
        totalCost: Number(modelTotalCost.toFixed(6))
      },
      pricing: {
        inputPricePerMillion: pricing.input,
        outputPricePerMillion: pricing.output
      }
    });
  }

  return {
    details: results,
    summary: {
      totalCost: Number(totalCost.toFixed(2)),
      currency: 'USD'
    }
  };
}

const costAnalysis = calculateCosts(data);

return [
  {
    json: costAnalysis,
    pairedItem: [{ item: 0 }]
  }
];
